WITH cohort AS (
  SELECT DISTINCT p.id FROM patient p JOIN examination e ON e.id = p.id WHERE p.birthday > DATE '1960-01-01'
)
SELECT count(*) AS never_raised_rnp_patients
FROM cohort c
WHERE NOT EXISTS (
  SELECT 1 FROM laboratory l
  WHERE l.id = c.id AND l.rnp ~ '^[0-9]+(\.[0-9]+)?$' AND l.rnp::numeric > 10
);

