WITH last_edit AS (
  SELECT DISTINCT ON (postid) postid, userid, id FROM posthistory ORDER BY postid, id DESC
)
SELECT count(*) AS n, count(*) FILTER (WHERE p.lasteditoruserid = le.userid) AS match, count(*) FILTER (WHERE p.lasteditoruserid IS NULL) AS p_null, count(*) FILTER (WHERE le.userid IS NULL) AS h_null
FROM posts p LEFT JOIN last_edit le ON le.postid = p.id
WHERE p."creaiondate" >= '2012-01-01' AND p."creaiondate" < '2013-01-01';

WITH last_edit AS (
  SELECT DISTINCT ON (postid) postid, userid, id, posthistorytypeid FROM posthistory WHERE posthistorytypeid IN (4,5,6) ORDER BY postid, id DESC
)
SELECT count(*) AS n, count(le.postid) AS has_edit, count(*) FILTER (WHERE p.lasteditoruserid = le.userid) AS match, count(*) FILTER (WHERE p.lasteditoruserid IS NULL) AS p_null, count(*) FILTER (WHERE p.lasteditoruserid IS NULL AND le.userid IS NOT NULL) AS p_null_h_has
FROM posts p LEFT JOIN last_edit le ON le.postid = p.id
WHERE p."creaiondate" >= '2012-01-01' AND p."creaiondate" < '2013-01-01';
